Expression:
// VAR CurrentWeek =
//     MAX('CALENDAR'[WEEK_OF_MONTH_NO])
// VAR CurrentMonth =
//     MAX('CALENDAR'[MONTH_YEAR_INTEGER])
// RETURN
// CALCULATE(
//     [Total Amount],
//     FILTER(
//         ALL('CALENDAR'),
//         'CALENDAR'[MONTH_YEAR_INTEGER] = CurrentMonth &&
//         'CALENDAR'[WEEK_OF_MONTH_NO] = CurrentWeek - 1
//     )
// )

VAR CurrentMinDate = MIN('CALENDAR'[Date])
VAR PrevWeekAnchorDate = CurrentMinDate - 7
VAR PrevMonth =
    CALCULATE(
        MAX('CALENDAR'[MONTH_YEAR_INTEGER]),
        FILTER(ALL('CALENDAR'), 'CALENDAR'[Date] = PrevWeekAnchorDate)
    )
VAR PrevWeek =
    CALCULATE(
        MAX('CALENDAR'[WEEK_OF_MONTH_NO]),
        FILTER(ALL('CALENDAR'), 'CALENDAR'[Date] = PrevWeekAnchorDate)
    )
RETURN
CALCULATE(
    [Total Amount],
    FILTER(
        ALL('CALENDAR'),
        'CALENDAR'[MONTH_YEAR_INTEGER] = PrevMonth &&
        'CALENDAR'[WEEK_OF_MONTH_NO] = PrevWeek
    )
)

// VAR MaxWeek =
// CALCULATE(
//     MAX('CALENDAR'[WEEK_OF_MONTH]),
//     REMOVEFILTERS(Purchase_History[preference]))
// RETURN
// CALCULATE(
//     [Total Amount],
//     REMOVEFILTERS('CALENDAR'[WEEK_OF_MONTH]),
//     ALLSELECTED(Purchase_History[preference]),
//     'CALENDAR'[WEEK_OF_MONTH] = MaxWeek
// )
VAR MaxWeek =
    CALCULATE(
        MAX('CALENDAR'[WEEK_OF_MONTH]),
        REMOVEFILTERS(Purchase_History[preference], Purchase_History[preference_sort])
    )
RETURN
CALCULATE(
    [Total Amount],
    REMOVEFILTERS('CALENDAR'[WEEK_OF_MONTH]),
    'CALENDAR'[WEEK_OF_MONTH] = MaxWeek
)

